import{_ as t,a,b as o}from"./chunks/ugso_jinja_composed_value.CVdJqvsB.js";import{_ as n,o as i,c as s,a3 as r}from"./chunks/framework.BlfGB29P.js";const d="/assets/blocks-for-ha/blocks/en/ugso_and.png",c="/assets/blocks-for-ha/blocks/en/ugso_or.png",l="/assets/blocks-for-ha/jinja/en.png",k=JSON.parse('{"title":"Extended HA automations and Jinja","description":"Triggers, conditions, targets, action groups and experimental Jinja recognition.","frontmatter":{"title":"Extended HA automations and Jinja","description":"Triggers, conditions, targets, action groups and experimental Jinja recognition."},"headers":[],"relativePath":"en/projects/blocks-for-ha/advanced.md","filePath":"en/projects/blocks-for-ha/advanced.md","lastUpdated":1793006827000}'),p={name:"en/projects/blocks-for-ha/advanced.md"};function g(m,e,h,u,b,f){return i(),s("div",null,[...e[0]||(e[0]=[r('<h1 id="extended-ha-automations-and-jinja" tabindex="-1">Extended HA automations and Jinja <a class="header-anchor" href="#extended-ha-automations-and-jinja" aria-label="Permalink to &quot;Extended HA automations and Jinja&quot;">​</a></h1><h2 id="ha-options-through-the-gear-since-0-1-61" tabindex="-1">HA options through the gear since 0.1.61 <a class="header-anchor" href="#ha-options-through-the-gear-since-0-1-61" aria-label="Permalink to &quot;HA options through the gear since 0.1.61&quot;">​</a></h2><p>Drag an option from the left into the gear popup list. Each option adds its own row below required fields. Order and deliberately selected empty rows are saved in the project. Removing an option resets its value. Imported options, including <code>false</code>, <code>0</code>, lists and templates, appear automatically and remain unchanged on load. All labels are available in DE/EN/FR.</p><p><img src="'+t+'" alt="Compact HA step"></p><table tabindex="0"><thead><tr><th>Reviewed HA blocks</th><th>Required fields / gear options</th></tr></thead><tbody><tr><td>All extended triggers and generic HA trigger</td><td>Type and core fields remain. Additional limits, state filters, duration, attributes, templates, event filters, device association, ID, name, enabled and variables depend on the trigger.</td></tr><tr><td>Extended HA condition</td><td>Type and core fields; optional time limits, weekdays, attributes, duration, name and enabled.</td></tr><tr><td>Extended HA step</td><td>Action and entity; device, area, floor, label, data, response variable, name, enabled, error handling and metadata added individually.</td></tr><tr><td>Target action, generic action, fire event</td><td>Required name and target remain; data, response variable, lists, metadata or step options.</td></tr><tr><td>Wait for triggers, time pattern</td><td>Trigger chain remains; timeout, timeout handling and step options. Time fields selected individually; valid YAML needs at least one.</td></tr><tr><td>Calendar, temperature, integration triggers</td><td>Core fields and required thresholds remain; additional targets, options and ID.</td></tr><tr><td>Simple triggers</td><td>ID, multiple entities/states/times, any change, hold time, sun offset and event filter depending on the block.</td></tr><tr><td>Simple actions/values, variables</td><td>No unnecessary gear for core-only inputs. Variable names and values remain directly editable.</td></tr><tr><td>If, case, parallel, objects, lists and functions</td><td>Existing specialized gear editors remain available.</td></tr></tbody></table><p><strong>and</strong>, <strong>or</strong> and <strong>not</strong> are separate palette blocks. and/or have expandable gear editors without an operator selector; not has one input. Existing combined groups remain readable, including multiple negation inputs. YAML import uses separate variants where exactly equivalent.</p><p><img src="'+d+'" alt="and"></p><p><img src="'+c+'" alt="or"></p><p>Verification covers rendering every block definition in DE/EN/FR, project/YAML compatibility and adding/removing options. Entities, integrations and runtime data still need verification in HA.</p><p>Since <strong>0.1.43</strong>, extended HA blocks offer labelled inputs instead of one large JSON object. There are still 163 block types; <strong>HA extended</strong> and <strong>Jinja (experimental)</strong> complement simple blocks. Import checks the supported structure; verify integrations, device IDs, templates and execution in Home Assistant.</p><p>All 15 classic extended triggers, general conditions and steps, integration targets/options, calendars, temperature thresholds, time patterns, variables and wait/step options use structured fields. <strong>numeric_state</strong>, for example, provides entity, above, below, attribute, template, duration and ID. Empty optional fields are omitted; both bounds can be edited independently. Entity fields support HA search, manual IDs, JSON lists and templates. When changing the type of a general block, add any further fields through its options if needed.</p><p>Enter lists and objects as JSON; <code>null</code> is an explicit null, <code>&quot;null&quot;</code> is text. States and payloads remain text. Unchanged values retain their original types and exact Jinja source. <strong>Additional options (JSON)</strong> retains extra properties. Complex data and nested branches remain separate JSON fields; they are not automatically decomposed into connected branches. Older JSON projects automatically load the new fields; YAML import/export and saved projects remain compatible.</p><p><img src="'+a+'" alt="Numeric-state trigger with separate inputs"></p><p>Original specification: <a href="https://www.home-assistant.io/docs/automation/trigger/" target="_blank" rel="noreferrer">HA triggers</a>, <a href="https://www.home-assistant.io/docs/scripts/conditions/" target="_blank" rel="noreferrer">HA conditions</a>, <a href="https://www.home-assistant.io/docs/scripts/" target="_blank" rel="noreferrer">HA steps</a>.</p><h2 id="triggers-and-conditions" tabindex="-1">Triggers and conditions <a class="header-anchor" href="#triggers-and-conditions" aria-label="Permalink to &quot;Triggers and conditions&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Area</th><th>Supported additions</th></tr></thead><tbody><tr><td>State</td><td>Multiple entities; <code>from</code>, <code>to</code>, <code>not_from</code>, <code>not_to</code>, lists and <code>null</code>; attributes and <code>for</code>.</td></tr><tr><td>Numbers</td><td>Both bounds, helper entities as bounds, attributes, <code>value_template</code>, duration and multiple entities.</td></tr><tr><td>Time</td><td>Times and lists, time helpers/sensors, time source with offset, weekdays and time patterns.</td></tr><tr><td>Sun and HA</td><td>Sunrise/sunset with offset; startup and shutdown.</td></tr><tr><td>More triggers</td><td>MQTT, template, webhook, zone, device, tag, conversation, geolocation, event and classic calendar.</td></tr><tr><td>Integrations</td><td><code>calendar.event_started/ended</code>, <code>temperature.changed</code>, <code>power.changed</code>, <code>motion.detected</code>, <code>timer.finished</code>. Device, area, floor and label targets are also supported.</td></tr><tr><td>Conditions</td><td>Time/weekday, state with lists/attribute/duration/<code>match</code>, numeric bounds, sun, zone, device, trigger ID, template and nested AND/OR/NOT. Template shorthand is preserved.</td></tr></tbody></table><p>The integration block provides a dropdown for power, motion and timers. Enter targets and options separately. Changing the integration replaces unchanged example values; custom values remain. Extended JSON triggers support <code>alias</code>, <code>enabled</code>, <code>id</code> and trigger variables. Unknown types and unsupported fields are rejected with a message.</p><h2 id="targets-variables-and-options" tabindex="-1">Targets, variables and options <a class="header-anchor" href="#targets-variables-and-options" aria-label="Permalink to &quot;Targets, variables and options&quot;">​</a></h2><p><strong>HA action with target type</strong> offers <code>entity_id</code>, <code>device_id</code>, <code>area_id</code>, <code>floor_id</code> and <code>label_id</code>. Enter an ID, JSON list or HA template. Use <strong>HA step (extended)</strong> for multiple target types together. Action data may be an object or a complete HA template; import preserves either form.</p><p>Variables also support lists and nested objects. Existing variables have individual value fields; add new names through additional options. Common step options <code>alias</code>, <code>enabled</code>, <code>continue_on_error</code>, response variables and metadata have separate inputs. <code>enabled</code> accepts a Boolean or HA template; <code>continue_on_error</code> accepts a Boolean.</p><p>Under <strong>Project &amp; description → HA options</strong>, edit <code>variables</code>, <code>trigger_variables</code>, <code>initial_state</code>, <code>trace.stored_traces</code> and <code>max_exceeded</code>. <strong>Apply</strong> accepts valid options only. Omitted options are removed; <code>{}</code> removes every option managed by this field. Name and execution mode remain separate. An automation without <code>alias</code> can be imported; its filename falls back to <code>automation.yaml</code>. All app controls follow the selected language since 0.1.46.</p><h2 id="waiting-and-action-groups" tabindex="-1">Waiting and action groups <a class="header-anchor" href="#waiting-and-action-groups" aria-label="Permalink to &quot;Waiting and action groups&quot;">​</a></h2><ul><li><strong>Wait for trigger</strong> connects a trigger chain and offers <code>timeout</code> / <code>continue_on_timeout</code> in its options field.</li><li><strong>Action group</strong> generates a native <code>sequence</code> with connectable steps.</li><li><strong>Parallel</strong> starts native parallel branches. The <strong>gear</strong> allows 1–100 branches. Removing an occupied branch leaves its contents disconnected; reconnect or delete them.</li><li><strong>Continue only if</strong> generates a condition as an action step. Event, Assist response and scene have dedicated blocks.</li><li>Repeats also support literal lists/objects for <code>for_each</code>; delays accept combined units and fractions. Extended or mixed branch shapes remain JSON steps.</li></ul><p>These blocks export native HA flows. Execution takes place in HA; there is no local script engine.</p><h2 id="jinja-experimental" tabindex="-1">Jinja (experimental) <a class="header-anchor" href="#jinja-experimental" aria-label="Permalink to &quot;Jinja (experimental)&quot;">​</a></h2><p>Since <strong>0.1.41</strong>, <strong>Jinja einlesen</strong> can decompose templates into editable nested blocks. Paste the template, check the preview, leave <strong>Decompose into editable blocks</strong> selected and optionally choose <strong>Als Bedingung</strong>. <strong>Block erstellen</strong> places the connected structure beside the automation. Connect the outer value block to a variable assignment or value input; connect the condition block to a Boolean input. Disabling decomposition creates an original-text block.</p><p><img src="'+o+'" alt="Composed Jinja value block"></p><p>Example: <code>Water: {{ states(&#39;sensor.water&#39;) | float(0) | round(1) }} °C</code> becomes text parts and an output containing an entity function, <code>float</code> and <code>round</code> blocks. The entity field opens the existing search. Edit entities, filters, arguments and rounding precision separately. YAML import decomposes matching template values, for example in a single variable assignment, and template conditions. More specific existing shapes are retained. Templates inside action-data/options JSON remain in the JSON field.</p><p><img src="'+l+'" alt="Editable structure of the example"></p><table tabindex="0"><thead><tr><th>Supported parts</th><th>Representation</th></tr></thead><tbody><tr><td><code>states</code>, <code>state_attr</code>, <code>is_state</code>, <code>is_state_attr</code> with a fixed entity ID</td><td>Entity function with search field and argument sockets</td></tr><tr><td><code>now()</code>, simple variable names, numbers, quoted strings, Boolean and <code>none</code></td><td>Expression blocks; Jinja variable names are text fields</td></tr><tr><td><code>float</code>, <code>int</code>, <code>round</code>, <code>default</code>, <code>abs</code>, <code>lower</code>, <code>upper</code>, <code>trim</code>, <code>length</code>, <code>string</code>, <code>list</code>, <code>join</code>, <code>replace</code></td><td>Nested filters with 0–3 positional arguments</td></tr><tr><td><code>+</code>, <code>-</code>, <code>*</code>, <code>/</code>, <code>//</code>, <code>%</code>, <code>~</code>, comparisons, <code>and</code>, <code>or</code>, <code>not</code></td><td>Calculations/comparisons with explicit parentheses</td></tr><tr><td><code>value if condition else other_value</code></td><td>Conditional value selection</td></tr><tr><td>Text, <code>{{ ... }}</code>, simple <code>{% if ... %}...{% else %}...{% endif %}</code></td><td>Text, output, join and if/else blocks</td></tr><tr><td><code>{% for item in items %}...{% else %}...{% endfor %}</code></td><td>Simple loop over an expression, optional empty case and nested parts</td></tr></tbody></table><p><strong>Preserving originals:</strong> Unchanged structures retain exact original text, including whitespace, after project reload and undo/redo. Editing generates newly formatted Jinja; restoring fields to the same structure restores the original. Blockly projects save the structure and original. YAML saves the template text, which is analysed again on import.</p><div class="warning custom-block"><p class="custom-block-title">Decomposition limits</p><p>This is an original parser for a limited Jinja subset. If any part is unsupported, the <strong>entire template</strong> remains an editable original block. Examples include <code>set</code>, <code>namespace</code>, object/list access, list/object literals, tests such as <code>is defined</code>, chained comparisons, <code>elif</code>, named arguments, unknown functions/filters, comments and whitespace-control markers. No partial decomposition, syntax guarantee or local execution. Outer value blocks accept complete templates; only a single Jinja output can be embedded in another calculation. Missing inputs or invalid literals prevent export. Limits: 10000 characters, 100 template parts and bounded nesting. Jinja variable names are not automatically renamed with other Blockly variables. Home Assistant evaluates the template; test there.</p></div><p>Blockly projects also retain shapes and positions. YAML → Blockly → export preserves supported values, including omitted optional fields. Limits: 100 chain entries/branches, 10 flow/condition nesting levels and bounded data/template sizes. Integration-specific device options are not exhaustive; rejected fields are never silently removed.</p><h2 id="original-sources-and-licenses" tabindex="-1">Original sources and licenses <a class="header-anchor" href="#original-sources-and-licenses" aria-label="Permalink to &quot;Original sources and licenses&quot;">​</a></h2><p>Original UGSo implementation based on public specifications, without copying ioBroker’s execution engine. Blockly/plugin licenses appear under <strong>Über &amp; Lizenzen</strong>; the app uses Apache-2.0.</p><ul><li><a href="https://www.home-assistant.io/docs/automation/trigger/" target="_blank" rel="noreferrer">HA triggers</a>, <a href="https://www.home-assistant.io/docs/scripts/conditions/" target="_blank" rel="noreferrer">conditions</a>, <a href="https://www.home-assistant.io/docs/scripts/" target="_blank" rel="noreferrer">script building blocks</a> and <a href="https://www.home-assistant.io/docs/automation/yaml/" target="_blank" rel="noreferrer">automation YAML</a>.</li><li><a href="https://www.home-assistant.io/triggers/power.changed/" target="_blank" rel="noreferrer">Power changed</a>, <a href="https://www.home-assistant.io/triggers/motion.detected/" target="_blank" rel="noreferrer">motion detected</a>, <a href="https://www.home-assistant.io/triggers/timer.finished/" target="_blank" rel="noreferrer">timer finished</a>.</li><li><a href="https://jinja.palletsprojects.com/en/stable/templates/" target="_blank" rel="noreferrer">Jinja templates</a> and <a href="https://www.home-assistant.io/docs/configuration/templating/" target="_blank" rel="noreferrer">HA templates</a>.</li><li><a href="https://docs.blockly.com/guides/create-custom-blocks/overview/" target="_blank" rel="noreferrer">Blockly custom blocks</a> and <a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/tree/master/blocks_for_ha" target="_blank" rel="noreferrer">UGSo source</a>.</li></ul>',36)])])}const x=n(p,[["render",g]]);export{k as __pageData,x as default};
